// === Tab: mySketch ===
let circles = [];
let pal;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 255);
  noStroke();
  pal = new Palette().randomSoft();
  for (let i = 0; i < 50; i++) {
    circles.push(new ColorCircle());
  }
}

function draw() {
  background(255);

  for (let c of circles) {
    c.update();
    c.show();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

class ColorCircle {
  constructor() {
    this.reset();
  }

  reset() {
    this.x = random(width);
    this.y = random(height);
    this.r = random(20, 80);
    this.c = pal.mix(random(1));
    this.alpha = 0;
    this.alphaSpeed = random(1, 3);
    this.fadeIn = true;
  }

  update() {
    if (this.fadeIn) {
      this.alpha += this.alphaSpeed;
      if (this.alpha >= 255) this.fadeIn = false;
    } else {
      this.alpha -= this.alphaSpeed;
      if (this.alpha <= 0) this.reset();
    }
  }

  show() {
    fill(this.c.levels[0], this.c.levels[1], this.c.levels[2], this.alpha);
    ellipse(this.x, this.y, this.r * 2);
  }
}

class Palette {
  constructor() {
    this.h1 = 0;
    this.h2 = 0;
    this.h3 = 0;
    this.s = 0;
    this.b = 0;
  }

  randomSoft() {
    const base = random(0, 360);
    this.h1 = base;
    this.h2 = base + random(110, 160);
    this.h3 = base + random(200, 260);
    this.s = random(0.55, 0.85);
    this.b = random(0.8, 0.98);
    return this;
  }

  mix(t) {
    const seg = random(1) < 0.5 ? 0 : 1;
    const hA = seg === 0 ? this.h1 : this.h2;
    const hB = seg === 0 ? this.h2 : this.h3;
    colorMode(HSB, 360, 1, 1, 1);
    const c = lerpColor(
      color(this.normHue(hA), this.s, this.b, 1),
      color(this.normHue(hB), this.s, this.b, 1),
      constrain(t, 0, 1)
    );
    colorMode(HSB, 255);
    return c;
  }

  normHue(h) {
    let nh = h % 360;
    if (nh < 0) nh += 360;
    return nh;
  }
}

